/// <summary>
/// MPJ_28155_SalesFinalisation 3.7.2 Automatic shipment creation periodic task
/// </summary>
[DataContractAttribute]
class METSalesOrderShipmentCreationContract implements SysOperationValidatable
{
    str packedQuery;
    RecordSortedList salesOrderRecordSortedList;

}

Method.Source:
    [
        DataMemberAttribute,
        AifQueryTypeAttribute('_packedQuery', queryStr(METSalesOrderShipmentCreationQuery))
    ]
    public str parmPackedQuery(str _packedQuery = packedQuery)
    {
        packedQuery = _packedQuery;

        return packedQuery;
    }

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false), AifCollectionTypeAttribute('_salesOrderRecordSortedList', Types::Class, classStr(RecordSortedList))]
    public RecordSortedList parmSalesOrderRecordSortedList(RecordSortedList _salesOrderRecordSortedList = salesOrderRecordSortedList)
    {
        salesOrderRecordSortedList = _salesOrderRecordSortedList;

        return salesOrderRecordSortedList;
    }

    /// <summary>
    /// Determines whether the parameters are valid.
    /// </summary>
    /// <returns>
    /// true when the parameters are valid; otherwise, false.
    /// </returns>
    public boolean validate()
    {
        boolean isValid = true;
        Query query;
        QueryBuildDataSource qbdsSalesTable;
        str shipDateRequestedFilter, warehouseFilter;

        // For the batch scenario with a query, we need to validate below ranges are set
        if (packedQuery)
        {
            query = this.getQuery();

            qbdsSalesTable = query.dataSourceTable(tableNum(SalesTable));

            shipDateRequestedFilter = qbdsSalesTable.findRange(fieldNum(SalesTable, ShippingDateRequested)).value();
            warehouseFilter = qbdsSalesTable.findRange(fieldNum(SalesTable, InventLocationId)).value();

            // if no requested ship date range value
            if (!shipDateRequestedFilter)
            {
                isValid = checkFailed(strFmt("@SYS84753", fieldId2PName(tableNum(SalesTable), fieldNum(SalesTable, ShippingDateRequested))));
            }

            // if no primary warehouse range value
            if (!warehouseFilter)
            {
                isValid = checkFailed(strFmt("@SYS84753", fieldId2PName(tableNum(SalesTable), fieldNum(SalesTable, InventLocationId))));
            }
        }
        
        return isValid;
    }
